// Laboratory end-to-end check of CA proposals, issuer certificates, signed
// CA approval, activation, suspension, reactivation and retirement
// (migrations 0025–0027, ADR-0013 to ADR-0015)
// through Keycloak sign-ins and the management API of the Compose stack. The root key is generated by OpenSSL with
// scripts/lab/create-lab-root.sh into the ignored .lab-keys/; only the
// certificate is sent. Run with .env.lab loaded, after compose-smoke.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { rmSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { requiredEnv, signIn } from './keycloak-login.mjs';

const realm = 'http://127.0.0.1:8080/realms/trust-lab';
const api = 'http://127.0.0.1:8081';
const repository = fileURLToPath(new URL('../../', import.meta.url));
const suffix = randomUUID().slice(0, 8);
const name = `E2E Lab Root ${suffix}`;
const results = [];

async function token(username, envName) {
  const session = await signIn(realm, username, requiredEnv(envName));
  assert.ifError(session.error);
  return session.access_token;
}

async function send(method, path, accessToken, body, key = randomUUID()) {
  const headers = { authorization: `Bearer ${accessToken}` };
  if (body !== undefined) Object.assign(headers, { 'content-type': 'application/json', 'idempotency-key': key });
  const response = await fetch(`${api}${path}`, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
  const text = await response.text();
  return { status: response.status, replayed: response.headers.get('idempotent-replayed') === 'true',
    body: text ? JSON.parse(text) : null };
}

async function check(label, run) {
  await run();
  results.push(label);
  console.log(`ok - ${label}`);
}

// Generates a root outside the platform, as an administrator would.
function labRoot(displayName) {
  return execFileSync('sh', ['scripts/lab/create-lab-root.sh', displayName], { cwd: repository }).toString();
}

const admin = await token('lab-ca-admin', 'TRUST_LAB_PW_CA_ADMIN');
const operator = await token('lab-operator', 'TRUST_LAB_PW_OPERATOR');
const reader = await token('lab-reader', 'TRUST_LAB_PW_READER');
const caApprover1 = await token('lab-ca-approver-1', 'TRUST_LAB_PW_CA_APPROVER_1');
const caApprover2 = await token('lab-ca-approver-2', 'TRUST_LAB_PW_CA_APPROVER_2');
const profileApprover = await token('lab-approver-1', 'TRUST_LAB_PW_APPROVER_1');
// Signs like a CA approver at the command line: OpenSSL, the approver's own
// key from scripts/lab/init-env.sh, DER output.
const sign = (keyName, claim) => execFileSync('openssl', ['dgst', '-sha256', '-sign', `${repository}.lab-keys/${keyName}.pem`], { input: claim }).toString('base64');
const proposal = (displayName = name) => ({ display_name: displayName, policy_version: 'v1', suite_id: 'ecdsa-p256-sha256' });
let caId;

try {
  await check('only an administrator proposes a CA, once per idempotency key', async () => {
    assert.equal((await send('POST', '/v1/ca-proposals', operator, proposal())).status, 403);
    assert.equal((await send('POST', '/v1/ca-proposals', admin, { ...proposal(), suite_id: 'ecdsa-p384-sha384' })).status, 422);
    const key = randomUUID();
    const created = await send('POST', '/v1/ca-proposals', admin, proposal(), key);
    assert.deepEqual([created.status, created.body.lifecycle_status], [201, 'PROPOSED']);
    caId = created.body.ca_id;
    const replay = await send('POST', '/v1/ca-proposals', admin, proposal(), key);
    assert.deepEqual([replay.status, replay.replayed, replay.body.ca_id], [200, true, caId]);
  });

  const path = () => `/v1/ca-proposals/${caId}/issuer-certificate`;
  await check('a root for another name, or a non-administrator, is refused', async () => {
    const other = labRoot(`E2E Other Root ${suffix}`);
    assert.equal((await send('POST', path(), admin, { certificate_pem: other })).status, 422);
    assert.equal((await send('POST', path(), operator, { certificate_pem: other })).status, 403);
    assert.equal((await send('POST', path(), admin, { certificate_pem: other, private_key_pem: 'x' })).status, 400);
  });

  await check('the OpenSSL root of the proposal is verified and recorded once', async () => {
    const pem = labRoot(name);
    const registered = await send('POST', path(), admin, { certificate_pem: pem });
    assert.deepEqual([registered.status, registered.body.lifecycle_status], [201, 'KEY_ATTESTED']);
    const fingerprint = execFileSync('openssl', ['x509', '-outform', 'DER'], { input: pem });
    const expected = execFileSync('openssl', ['dgst', '-sha256', '-r'], { input: fingerprint }).toString().split(' ')[0];
    assert.equal(registered.body.certificate_sha256, expected);
    // The proposal already has its certificate: any other root is refused.
    assert.equal((await send('POST', path(), admin, { certificate_pem: labRoot(`${name}B`) })).status, 409);
  });

  let fingerprint;
  await check('two CA approvers sign the exact claim; others and other keys are refused', async () => {
    const claims = `${path().replace('/issuer-certificate', '')}/decision-claims`;
    const decisions = claims.replace('decision-claims', 'decisions');
    assert.equal((await send('POST', claims, admin, { decision: 'approve' }, undefined)).status, 403);
    assert.equal((await send('POST', claims, profileApprover, { decision: 'approve' })).status, 403);
    const first = await send('POST', claims, caApprover1, { decision: 'approve' });
    assert.equal(first.status, 200);
    assert.match(first.body.claim, /^trust-platform\/ca-decision\/v1;decision=approve;/);
    fingerprint = /certificate_sha256=([0-9a-f]{64})/.exec(first.body.claim)[1];
    const decide = (who, keyName, claim) => send('POST', decisions, who,
      { decision: claim.decision, issued_at: claim.issued_at, signature_der_base64: sign(keyName, claim.claim) });
    // A profile approver key, or another CA approver's key, does not count.
    assert.equal((await decide(caApprover1, 'lab-approver-1', first.body)).status, 422);
    assert.equal((await decide(caApprover1, 'lab-ca-approver-2', first.body)).status, 422);
    const recorded = await decide(caApprover1, 'lab-ca-approver-1', first.body);
    assert.deepEqual([recorded.status, recorded.body.lifecycle_status, recorded.body.approval_count], [201, 'KEY_ATTESTED', 1]);
    assert.equal((await send('POST', claims, caApprover1, { decision: 'reject' })).status, 409);
    const second = await send('POST', claims, caApprover2, { decision: 'approve' });
    const approved = await decide(caApprover2, 'lab-ca-approver-2', second.body);
    assert.deepEqual([approved.status, approved.body.lifecycle_status, approved.body.approval_count], [201, 'APPROVED', 2]);
  });

  await check('an administrator activates the approved CA with its certificate digest, once', async () => {
    const activation = path().replace('/issuer-certificate', '/activation');
    assert.equal((await send('POST', activation, caApprover1, { certificate_sha256: fingerprint })).status, 403);
    assert.equal((await send('POST', activation, admin, { certificate_sha256: '0'.repeat(64) })).status, 409);
    const key = randomUUID();
    const active = await send('POST', activation, admin, { certificate_sha256: fingerprint }, key);
    assert.deepEqual([active.status, active.body.lifecycle_status, active.body.suite_id], [201, 'ACTIVE', 'ecdsa-p256-sha256']);
    const replay = await send('POST', activation, admin, { certificate_sha256: fingerprint }, key);
    assert.deepEqual([replay.status, replay.replayed], [200, true]);
    assert.equal((await send('POST', activation, admin, { certificate_sha256: fingerprint })).status, 409);
  });

  await check('one administrator suspends; reactivation and retirement need two signers and a non-deciding administrator', async () => {
    const base = path().replace('/issuer-certificate', '');
    assert.equal((await send('POST', `${base}/suspension`, caApprover1, { reason: 'e2e' })).status, 403);
    const suspended = await send('POST', `${base}/suspension`, admin, { reason: 'e2e key review' });
    assert.deepEqual([suspended.status, suspended.body.operational_state], [201, 'SUSPENDED']);
    assert.equal((await send('POST', `${base}/suspension`, admin, { reason: 'again' })).status, 409);
    const changeOf = async action => {
      const requested = await send('POST', `${base}/change-requests`, admin, { action, reason: `e2e ${action}` });
      assert.equal(requested.status, 201);
      return `${base}/change-requests/${requested.body.request_id}`;
    };
    const approveChange = async (request, who, keyName) => {
      const claim = await send('POST', `${request}/decision-claims`, who, { decision: 'approve' });
      assert.equal(claim.status, 200);
      assert.match(claim.body.claim, /^trust-platform\/ca-change-decision\/v1;decision=approve;/);
      return send('POST', `${request}/decisions`, who,
        { decision: 'approve', issued_at: claim.body.issued_at, signature_der_base64: sign(keyName, claim.body.claim) });
    };
    const reactivation = await changeOf('reactivate');
    assert.equal((await send('POST', `${reactivation}/decision-claims`, admin, { decision: 'approve' })).status, 403);
    assert.equal((await approveChange(reactivation, caApprover1, 'lab-ca-approver-2')).status, 422);
    assert.equal((await approveChange(reactivation, caApprover1, 'lab-ca-approver-1')).body.request_status, 'OPEN');
    assert.equal((await send('POST', `${reactivation}/application`, admin, {})).status, 409);
    assert.equal((await approveChange(reactivation, caApprover2, 'lab-ca-approver-2')).body.request_status, 'APPROVED');
    const reactivated = await send('POST', `${reactivation}/application`, admin, {});
    assert.deepEqual([reactivated.status, reactivated.body.operational_state], [201, 'ACTIVE']);
    const retirement = await changeOf('retire');
    await approveChange(retirement, caApprover1, 'lab-ca-approver-1');
    await approveChange(retirement, caApprover2, 'lab-ca-approver-2');
    const retired = await send('POST', `${retirement}/application`, admin, {});
    assert.deepEqual([retired.status, retired.body.operational_state], [201, 'RETIRED']);
    assert.equal((await send('POST', `${base}/change-requests`, admin, { action: 'reactivate', reason: 'no' })).status, 409);
  });

  await check('administrators and approvers list proposals; readers cannot and see no new CA', async () => {
    const listed = await send('GET', '/v1/ca-proposals', admin);
    assert.equal(listed.status, 200);
    const mine = listed.body.find(item => item.ca_id === caId);
    assert.deepEqual([mine.lifecycle_status, mine.display_name, mine.custody, mine.approval_count], ['RETIRED', name, 'lab-software-file', 2]);
    assert.ok(mine.decided_at && mine.activated_at);
    assert.equal((await send('GET', '/v1/ca-proposals', caApprover2)).body.find(item => item.ca_id === caId).lifecycle_status, 'RETIRED');
    assert.equal((await send('GET', '/v1/ca-proposals', reader)).status, 403);
    const cas = await send('GET', '/v1/cas', reader);
    assert.ok(cas.body.every(ca => ca.ca_id !== caId));
  });
} finally {
  // Software keys from this run are not kept.
  for (const slug of [name, `E2E Other Root ${suffix}`, `${name}B`]) {
    const file = slug.toLowerCase().replaceAll(' ', '-').replaceAll('.', '-');
    rmSync(`${repository}.lab-keys/ca-root-${file}.pem`, { force: true });
    rmSync(`${repository}.lab-keys/ca-root-${file}.crt`, { force: true });
  }
}

console.log(`Laboratory CA proposal suite passed: ${results.length} cases (proposal ${caId}).`);
